\begin{theorem}
\label{theo:nocond}
For any trigonometric polynomial $f$ of degree less than $2r$, we have, for any $s \geqslant 3r$, and for $\bar{f} = \hat{f}(0)$ the mean-value of $f$:
\[
\varepsilon(f,s) \leqslant  \| f - \bar{f}\|_{\rm F}\cdot   
\Big[  \Big( 1 - \frac{6r^2}{s^2} \Big)^{-d} - 1 \Big] \sim_{s \to +\infty} \| f - \bar{f} \|_{\rm F}\cdot    \frac{ 6 r^2 d }{s^2}.
\]
\end{theorem}

